#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    cin >> n >> mod;

    vector<long long> dp_array(n + 1, 0);
    long long total_value = 1;
    dp_array[1] = 1;

    for (int i = 2; i <= n; ++i) {
        int limit = (int) sqrt(i) + 1;
        long long current_sum = total_value;

        for (int f = 2; f < limit; ++f) {
            current_sum = (current_sum + dp_array[i / f]) % mod;
        }

        int end_point = i;
        for (int j = 1; j <= i / limit; ++j) {
            int next_point = i / (j + 1);
            current_sum = (current_sum + (end_point - next_point) * dp_array[j]) % mod;
            end_point = next_point;
        }

        total_value = (total_value + current_sum) % mod;
        dp_array[i] = current_sum;
    }

    cout << dp_array[n] << "\n";

    return 0;
}
